B.hero=function(b){return '<section class="hero"><div class="hero-in">'+(b.emoji?'<div class="hero-emoji">'+b.emoji+'</div>':'')+(b.kicker?'<p class="kicker">'+esc(b.kicker)+'</p>':'')+'<h1>'+esc(b.title)+'</h1><p class="lead">'+esc(b.sub||'')+'</p><div class="row">'+(b.cta||[]).map(function(c,i){return '<button class="btn '+(i?'ghost':'')+'" data-act="go" data-p="'+c[1]+'">'+esc(c[0])+'</button>'}).join('')+'</div></div></section>'};
B.text=function(b){return '<section class="card"><h2>'+esc(b.h)+'</h2>'+(b.p||'').split('\n').map(function(x){return '<p>'+esc(x)+'</p>'}).join('')+'</section>'};
B.features=function(b){return '<section>'+(b.h?'<h2 class="sec">'+esc(b.h)+'</h2>':'')+'<div class="grid">'+b.items.map(function(f){return '<div class="card feat"><div class="fe">'+f[0]+'</div><h3>'+esc(f[1])+'</h3><p class="muted">'+esc(f[2])+'</p></div>'}).join('')+'</div></section>'};
B.stats=function(b){return '<section class="grid stats">'+b.items.map(function(s){var v=s.value;if(s.col){var l=rows(s.col);if(s.where)l=l.filter(function(x){return String(x[s.where[0]])===String(s.where[1])});v=s.sum?l.reduce(function(a,x){return a+(+x[s.sum]||0)},0):l.length;if(s.money)v='$'+v.toLocaleString()}return '<div class="card stat"><b>'+esc(v)+'</b><span class="muted">'+esc(s.label)+'</span></div>'}).join('')+'</section>'};
B.chart=function(b){var g={},l=rows(b.col);l.forEach(function(x){var k=x[b.by]||'Other';g[k]=(g[k]||0)+(b.value?(+x[b.value]||0):1)});var ks=Object.keys(g),mx=Math.max.apply(null,ks.map(function(k){return g[k]}).concat([1]));
 return '<section class="card"><h2>'+esc(b.title||'Chart')+'</h2>'+(ks.length?ks.map(function(k){return '<div class="bar"><span>'+esc(k)+'</span><i style="width:'+Math.round(g[k]/mx*100)+'%"></i><b>'+(b.money?'$':'')+g[k]+'</b></div>'}).join(''):'<p class="muted">Nothing yet.</p>')+'</section>'};
function fieldsOf(n){return (C.cols[n]||{}).fields||[['title','Title','text']]}
function cell(f,x){var v=x[f[0]];if(f[2]==='check')return v?'✅':'⬜';if(f[2]==='money')return '$'+(+v||0).toLocaleString();return esc(v)}
B.crud=function(b){var n=b.col,F=fieldsOf(n),c=C.cols[n]||{},qq=(q[n]||'').toLowerCase(),l=rows(n).filter(function(x){return !qq||JSON.stringify(x).toLowerCase().indexOf(qq)>=0});
 var head='<div class="crud-h"><h2>'+esc(b.title||n)+' <small class="muted">'+l.length+'</small></h2><button class="btn sm" data-act="add" data-c="'+n+'">+ Add '+esc(c.one||'item')+'</button></div>'+((b.search||C.features.indexOf('search')>=0)?'<input class="search" placeholder="Search '+esc(b.title||n)+'…" data-q="'+n+'" value="'+esc(q[n]||'')+'">':'');
 if(b.board){return '<section>'+head+'<div class="board">'+b.board.map(function(st,si){var it=l.filter(function(x){return (x[b.field||'status']||b.board[0])===st});return '<div class="lane"><h4>'+esc(st)+' <small>'+it.length+'</small></h4>'+it.map(function(x){return '<div class="card item"><b>'+esc(x[F[0][0]])+'</b>'+F.slice(1).filter(function(f){return f[0]!==(b.field||'status')&&x[f[0]]}).map(function(f){return '<small class="muted"> · '+cell(f,x)+'</small>'}).join('')+'<div class="acts">'+(si<b.board.length-1?'<button class="mini" data-act="move" data-c="'+n+'" data-id="'+x.id+'" data-v="'+esc(b.board[si+1])+'" data-f="'+(b.field||'status')+'">→ '+esc(b.board[si+1])+'</button>':'')+'<button class="mini" data-act="edit" data-c="'+n+'" data-id="'+x.id+'">Edit</button><button class="mini" data-act="del" data-c="'+n+'" data-id="'+x.id+'">✕</button></div></div>'}).join('')+'</div>'}).join('')+'</div></section>'}
 return '<section>'+head+(l.length?l.map(function(x){var chk=F.find(function(f){return f[2]==='check'});return '<div class="card item'+(chk&&x[chk[0]]?' done':'')+'">'+(chk?'<button class="tick" data-act="toggle" data-c="'+n+'" data-id="'+x.id+'" data-f="'+chk[0]+'">'+(x[chk[0]]?'✅':'⬜')+'</button>':'')+'<div class="grow"><b>'+esc(x[F[0][0]])+'</b><div class="muted small">'+F.slice(1).filter(function(f){return f[2]!=='check'&&x[f[0]]!==undefined&&x[f[0]]!==''}).map(function(f){return esc(f[1])+': '+cell(f,x)}).join(' · ')+'</div></div><button class="mini" data-act="edit" data-c="'+n+'" data-id="'+x.id+'">Edit</button><button class="mini" data-act="del" data-c="'+n+'" data-id="'+x.id+'">✕</button></div>'}).join(''):'<p class="card muted">Nothing here yet — tap “Add”.</p>')+'</section>'};
B.posts=function(b){var l=rows(b.col);return '<section>'+(b.h?'<h2 class="sec">'+esc(b.h)+'</h2>':'')+'<div class="grid">'+l.map(function(p){return '<article class="card post" data-act="read" data-c="'+b.col+'" data-id="'+p.id+'"><div class="pe">'+(p.emoji||'📝')+'</div><small class="muted">'+esc(p.date||'')+(p.tag?' · '+esc(p.tag):'')+'</small><h3>'+esc(p.title)+'</h3><p class="muted">'+esc(String(p.body||'').slice(0,110))+'…</p><span class="link">Read more →</span></article>'}).join('')+'</div></section>'};
B.gallery=function(b){return '<section>'+(b.h?'<h2 class="sec">'+esc(b.h)+'</h2>':'')+'<div class="gal">'+b.items.map(function(g){return '<figure class="card"><div class="ge" style="background:linear-gradient(135deg,var(--accent),var(--accent2))">'+g[0]+'</div><figcaption>'+esc(g[1])+'</figcaption></figure>'}).join('')+'</div></section>'};
B.pricing=function(b){return '<section>'+(b.h?'<h2 class="sec">'+esc(b.h)+'</h2>':'')+'<div class="grid">'+b.plans.map(function(p){return '<div class="card plan'+(p[3]?' hot':'')+'">'+(p[3]?'<span class="badge">Most popular</span>':'')+'<h3>'+esc(p[0])+'</h3><div class="price">'+esc(p[1])+'</div><ul>'+p[2].map(function(f){return '<li>✓ '+esc(f)+'</li>'}).join('')+'</ul><button class="btn" data-act="go" data-p="'+(b.go||'contact')+'">Choose '+esc(p[0])+'</button></div>'}).join('')+'</div></section>'};
B.faq=function(b){return '<section class="card"><h2>'+esc(b.h||'FAQ')+'</h2>'+b.items.map(function(f){return '<details><summary>'+esc(f[0])+'</summary><p class="muted">'+esc(f[1])+'</p></details>'}).join('')+'</section>'};
B.quotes=function(b){return '<section><h2 class="sec">'+esc(b.h||'What people say')+'</h2><div class="grid">'+b.items.map(function(t){return '<blockquote class="card">“'+esc(t[0])+'”<footer class="muted">— '+esc(t[1])+'</footer></blockquote>'}).join('')+'</div></section>'};
B.timeline=function(b){return '<section class="card"><h2>'+esc(b.h||'Schedule')+'</h2><ol class="tl">'+b.items.map(function(t){return '<li><b>'+esc(t[0])+'</b> '+esc(t[1])+'</li>'}).join('')+'</ol></section>'};
B.cta=function(b){return '<section class="card cta"><h2>'+esc(b.h)+'</h2><p class="muted">'+esc(b.p||'')+'</p><button class="btn" data-act="go" data-p="'+(b.go||'contact')+'">'+esc(b.btn||'Get in touch')+'</button></section>'};
B.form=function(b){return '<section class="card"><h2>'+esc(b.h||'Contact us')+'</h2>'+(b.p?'<p class="muted">'+esc(b.p)+'</p>':'')+'<form data-form="'+b.col+'" data-ok="'+esc(b.ok||'Thanks — we got it!')+'">'+b.fields.map(function(f){return '<label>'+esc(f[1])+(f[2]==='area'?'<textarea name="'+f[0]+'" rows="4" required></textarea>':f[2]&&f[2].indexOf('select:')===0?'<select name="'+f[0]+'">'+f[2].slice(7).split('|').map(function(o){return '<option>'+esc(o)+'</option>'}).join('')+'</select>':'<input name="'+f[0]+'" type="'+(f[2]||'text')+'" required>')+'</label>'}).join('')+'<button class="btn">'+esc(b.btn||'Send')+'</button></form></section>'};
B.login=function(){var u=user();if(u)return '<section class="card"><h2>👋 Hi, '+esc(u.name)+'</h2><p class="muted">Signed in as '+esc(u.email)+'</p><button class="btn ghost" data-act="logout">Sign out</button></section>';
 return '<section class="card narrow"><h2>Sign in</h2><p class="muted small">Demo sign-in: kept on this device only'+(C.fullstack?' (POST /api/auth)':'')+'. Swap in a real auth provider when you go live.</p><form data-login><label>Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Password<input name="pw" type="password" minlength="4" required></label><button class="btn">Sign in / Create account</button></form></section>'};
B.settings=function(){return '<section class="card"><h2>⚙️ Settings</h2><div class="set"><span>Dark mode</span><button class="btn sm ghost" data-act="dark">'+(document.body.classList.contains('dark')?'On':'Off')+'</button></div><div class="set"><span>Export all data</span><button class="btn sm ghost" data-act="export">Download JSON</button></div><div class="set"><span>Reset to sample data</span><button class="btn sm ghost" data-act="reset">Reset</button></div></section>'};
B.api=function(){var cs=Object.keys(C.cols);return '<section class="card"><h2>🧱 API</h2><p class="muted small">'+(REAL?'Connected to the real server (server/server.js).':'Running the built-in mock API in your browser. Export the ZIP and run <code>node server/server.js</code> for the real Node server — same routes.')+'</p><table class="tbl"><tr><th>Method</th><th>Route</th></tr>'+cs.map(function(n){return '<tr><td>GET · POST</td><td><code>/api/'+n+'</code></td></tr><tr><td>GET · PATCH · DELETE</td><td><code>/api/'+n+'/:id</code></td></tr>'}).join('')+'<tr><td>POST</td><td><code>/api/auth</code></td></tr><tr><td>GET</td><td><code>/api/health</code></td></tr></table><div class="row">'+cs.map(function(n){return '<button class="btn sm ghost" data-act="try" data-c="'+n+'">Try GET /api/'+n+'</button>'}).join('')+'</div><pre id="out" class="out">'+esc(q.__out||'Tap a button to call the API.')+'</pre><h3>Request log</h3><div class="log">'+(log.length?log.map(function(r){return '<div><code>'+r.t+'</code> <b>'+r.m+'</b> '+esc(r.p)+' → <span class="'+(r.s<400?'ok':'bad')+'">'+r.s+'</span> <small class="muted">'+r.ms+'ms</small></div>'}).join(''):'<p class="muted small">No requests yet.</p>')+'</div></section>'};
/* ---- shell ---- */
function pageById(id){return C.pages.find(function(p){return p.id===id})||C.pages[0]}
function render(){var p=pageById(cur);cur=p.id;var gate=p.private&&C.features.indexOf('auth')>=0&&!user();
 document.querySelectorAll('[data-nav]').forEach(function(a){a.classList.toggle('on',a.getAttribute('data-nav')===cur)});
 $('#main').innerHTML=gate?'<section class="card narrow"><h2>🔒 Sign in first</h2><p class="muted">This page is for members.</p><button class="btn" data-act="go" data-p="account">Sign in</button></section>':p.blocks.map(function(b){return (B[b.type]||B.text)(b)}).join('');
 var s=document.activeElement&&document.activeElement.getAttribute&&document.activeElement.getAttribute('data-q');if(s){var el=document.querySelector('[data-q="'+s+'"]');if(el){el.focus();el.setSelectionRange(el.value.length,el.value.length)}}}
function go(id){location.hash='#/'+id}
function route(){var id=(location.hash.match(/^#\/(\w+)/)||[])[1]||C.pages[0].id;if(id!==cur){cur=id;render();window.scrollTo(0,0)}else render()}
function sheet(n,x){var F=fieldsOf(n),c=C.cols[n]||{};$('#sheet').innerHTML='<form class="sheet-in" data-save="'+n+'" data-id="'+(x?x.id:'')+'"><h3>'+(x?'Edit ':'Add ')+esc(c.one||'item')+'</h3>'+F.map(function(f){var v=x?x[f[0]]:(f[3]!==undefined?f[3]:'');var t=f[2]||'text';
 if(t==='check')return '<label class="chk"><input type="checkbox" name="'+f[0]+'"'+(v?' checked':'')+'> '+esc(f[1])+'</label>';
 if(t.indexOf('select:')===0)return '<label>'+esc(f[1])+'<select name="'+f[0]+'">'+t.slice(7).split('|').map(function(o){return '<option'+(o===v?' selected':'')+'>'+esc(o)+'</option>'}).join('')+'</select></label>';
 if(t==='area')return '<label>'+esc(f[1])+'<textarea name="'+f[0]+'" rows="3">'+esc(v)+'</textarea></label>';
 return '<label>'+esc(f[1])+'<input name="'+f[0]+'" type="'+(t==='money'?'number':t)+'" value="'+esc(v)+'"'+(f===F[0]?' required':'')+'></label>'}).join('')+'<div class="row"><button class="btn">Save</button><button type="button" class="btn ghost" data-act="close">Cancel</button></div></form>';$('#sheet').classList.add('on');var i=$('#sheet input,#sheet textarea');if(i)i.focus()}
function modal(html){$('#sheet').innerHTML='<div class="sheet-in">'+html+'<div class="row"><button class="btn ghost" data-act="close">Close</button></div></div>';$('#sheet').classList.add('on')}
document.addEventListener('click',function(e){if(e.target.id==='sheet'){e.target.classList.remove('on');return}var t=e.target.closest('[data-act]');if(!t)return;var a=t.getAttribute('data-act'),n=t.getAttribute('data-c'),id=t.getAttribute('data-id');
 if(a==='go'){go(t.getAttribute('data-p'));closeNav()}
 else if(a==='add')sheet(n);else if(a==='edit')sheet(n,rows(n).find(function(x){return x.id===id}));
 else if(a==='del'){if(confirm('Delete this?'))mut(n,'del',id).then(function(){toast('Deleted')})}
 else if(a==='toggle'){var f=t.getAttribute('data-f'),x=rows(n).find(function(x){return x.id===id});var v={};v[f]=!x[f];mut(n,'upd',id,v)}
 else if(a==='move'){var v2={};v2[t.getAttribute('data-f')]=t.getAttribute('data-v');mut(n,'upd',id,v2).then(function(){toast('Moved to '+t.getAttribute('data-v'))})}
 else if(a==='read'){var p=rows(n).find(function(x){return x.id===id});modal('<div class="pe big">'+(p.emoji||'📝')+'</div><small class="muted">'+esc(p.date||'')+'</small><h2>'+esc(p.title)+'</h2>'+String(p.body||'').split('\n').map(function(x){return '<p>'+esc(x)+'</p>'}).join(''))}
 else if(a==='close')$('#sheet').classList.remove('on');
 else if(a==='dark'){document.body.classList.toggle('dark');sset('dark',document.body.classList.contains('dark'));render()}
 else if(a==='logout'){sset('user',null);toast('Signed out');render()}
 else if(a==='export'){var d={};Object.keys(C.cols).forEach(function(k){d[k]=rows(k)});var u=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));var l=document.createElement('a');l.href=u;l.download=C.slug+'-data.json';l.click()}
 else if(a==='reset'){if(confirm('Reset everything to the sample data?')){Object.keys(C.cols).forEach(function(k){sset('col-'+k,seed(k))});boot()}}
 else if(a==='try'){api('GET','/api/'+n).then(function(r){q.__out=JSON.stringify(r,null,2).slice(0,1500);render()})}
 else if(a==='menu'){document.body.classList.toggle('navopen')}});
document.addEventListener('input',function(e){var n=e.target.getAttribute&&e.target.getAttribute('data-q');if(n){q[n]=e.target.value;render()}});
document.addEventListener('submit',function(e){var f=e.target;e.preventDefault();var d={};new FormData(f).forEach(function(v,k){d[k]=v});
 if(f.hasAttribute('data-save')){var n=f.getAttribute('data-save'),id=f.getAttribute('data-id');fieldsOf(n).forEach(function(x){if(x[2]==='check')d[x[0]]=!!d[x[0]];if(x[2]==='number'||x[2]==='money')d[x[0]]=+d[x[0]]||0});$('#sheet').classList.remove('on');mut(n,id?'upd':'add',id||undefined,d).then(function(){toast(id?'Saved':'Added')})}
 else if(f.hasAttribute('data-form')){d.date=new Date().toLocaleString();mut(f.getAttribute('data-form'),'add',undefined,d).then(function(){f.reset();toast(f.getAttribute('data-ok'))})}
 else if(f.hasAttribute('data-login')){var done=function(u){sset('user',{name:u.name,email:u.email});toast('Welcome, '+u.name);render()};C.fullstack?api('POST','/api/auth',{name:d.name,email:d.email}).then(done):done(d)}});
function closeNav(){document.body.classList.remove('navopen')}
function boot(){if(sget('dark',C.dark))document.body.classList.add('dark');else document.body.classList.remove('dark');
 if(!C.fullstack){route();return}
 $('#main').innerHTML='<p class="card muted">Connecting to the API…</p>';
 var ping=REAL?Promise.resolve():new Promise(function(res){var done=false;setTimeout(function(){if(!done){done=true;res()}},700);try{fetch('/api/health').then(function(r){return r.ok?r.json():null}).then(function(j){if(!done){done=true;if(j&&j.ok&&!j.mock)REAL=true;res()}}).catch(function(){if(!done){done=true;res()}})}catch(e){done=true;res()}});
 ping.then(function(){return Promise.all(Object.keys(C.cols).map(function(n){return api('GET','/api/'+n).then(function(l){cache[n]=l})}))}).then(route).catch(function(){route()})}
window.addEventListener('hashchange',route);boot();
